/**
 * Copyright 2017-2026, Voxel51, Inc.
 *
 * The view expression syntax tree, mirroring
 * `fiftyone/core/expression_ast.py`. The server owns the format; this is the
 * App's reading of it, and `src/__fixtures__/expressions.json` — generated by
 * the Python — is what holds the two in agreement.
 */

export type JSONValue =
  | string
  | number
  | boolean
  | null
  | JSONValue[]
  | { [key: string]: JSONValue };

/** A `ViewField`: `F("confidence")`. */
export interface FieldNode {
  t: "field";
  path: string;
}

/**
 * A literal. `as` marks values JSON cannot carry natively — dates and
 * timedeltas travel as milliseconds.
 */
export interface LiteralNode {
  t: "lit";
  v: JSONValue;
  as?: "date" | "timedelta";
}

/** An instance method or operator applied to a target. */
export interface CallNode {
  t: "call";
  op: string;
  self: Node;
  args?: Node[];
  kwargs?: Record<string, Node>;
}

/** A static constructor such as `E.any`. */
export interface StaticNode {
  t: "static";
  op: string;
  args?: Node[];
  kwargs?: Record<string, Node>;
}

export interface ListNode {
  t: "list";
  items: Node[];
}

export interface DictNode {
  t: "dict";
  entries: [Node, Node][];
}

/**
 * Raw MongoDB, for an expression that recorded no syntax — one built by handing
 * MongoDB straight to `ViewExpression`, or one from a view saved before the
 * format existed. Renders as `E(...)`, which is accurate but not editable as
 * structure.
 */
export interface MongoNode {
  t: "mongo";
  expr: JSONValue;
}

export type Node =
  | FieldNode
  | LiteralNode
  | CallNode
  | StaticNode
  | ListNode
  | DictNode
  | MongoNode;

/** The versioned envelope a persisted expression travels in. */
export interface Envelope {
  _fo_expr: {
    version: number;
    node: Node;
  };
}

export const AST_KEY = "_fo_expr";

/**
 * The tree format this build understands. A higher version is not rendered —
 * the reader falls back to the lowered form instead, on both sides: the App
 * shows json, the server keeps the Mongo it was sent.
 */
export const AST_VERSION = 1;

export const isEnvelope = (value: unknown): value is Envelope =>
  typeof value === "object" &&
  value !== null &&
  AST_KEY in (value as Record<string, unknown>);

/**
 * Whether every part of a tree has recorded syntax, and so can be rendered as
 * source. False for anything containing raw MongoDB.
 */
export const isReconstructible = (node: Node): boolean => {
  switch (node.t) {
    case "mongo":
      return false;
    case "field":
    case "lit":
      return true;
    case "list":
      return node.items.every(isReconstructible);
    case "dict":
      return node.entries.every(
        ([key, value]) => isReconstructible(key) && isReconstructible(value),
      );
    case "static":
      return operands(node).every(isReconstructible);
    case "call":
      return [node.self, ...operands(node)].every(isReconstructible);
  }
};

/** Positional and keyword operands of a call or static node. */
export const operands = (node: CallNode | StaticNode): Node[] => [
  ...(node.args ?? []),
  ...Object.values(node.kwargs ?? {}),
];
